prop w_shutter_big 33 1
text 34 3 "하역장 셔터. 아래가 반 뼘 들렸다. 밖에서 손수레 바퀴 자국이 들어와 있다." w=2
prop pallet_sacks 36 17
prop crate_o 37 12
